mapper.select:
SELECT rt.room_type_id, rt.tenant_id, rt.dept_id, rt.type_name, rt.type_code, rt.description, rt.standard_occupancy, rt.max_occupancy, rt.room_area, rt.bed_configuration, rt.amenities, rt.default_price, rt.status, rt.sort_order, rt.images, rt.create_dept, rt.create_by, rt.create_time, rt.update_by, rt.update_time, d.dept_name, COALESCE(r.room_count, 0) as room_count FROM pms_room_types rt LEFT JOIN sys_dept d ON rt.dept_id = d.dept_id LEFT JOIN ( SELECT room_type_id, COUNT(*) as room_count FROM pms_room_rooms WHERE del_flag = '0' GROUP BY room_type_id ) r ON rt.room_type_id = r.room_type_id WHERE rt.del_flag = '0'
AND rt.dept_id = #{deptId}
AND rt.type_name LIKE CONCAT('%', #{typeName}, '%')
AND rt.type_code LIKE CONCAT('%', #{typeCode}, '%')
AND rt.status = #{status}
ORDER BY rt.sort_order ASC, rt.room_type_id ASC

SELECT room_type_id, type_code, dept_id
FROM pms_room_types
WHERE type_code = #{typeCode}
AND dept_id = #{deptId}
AND del_flag = '0'

    AND room_type_id != #{excludeId}

LIMIT 1
